custom_css:
  /* 🐨字体导入 */
  @import url("https://fontsapi.zeoseven.com/256/main/result.css");
  @import url("https://fontsapi.zeoseven.com/873/main/result.css");

  /* 🐸全局变量 */
  :root {
    /* 字体 */
    --font1: "Huiwen-mincho";
    --font2: "寒蝉活黑体_復 Bold";
    --mainFontFamily: var(--font1);
    /* 颜色 */
    --active: var(--SmartThemeBodyColor);
    --black70a: rgba(var(--SmartThemeCheckboxBgColorR),var(--SmartThemeCheckboxBgColorG),var(--SmartThemeCheckboxBgColorB),0.5);
    --golden: var(--SmartThemeBodyColor);
    --fullred: var(--SmartThemeBodyColor);
    --black30a: rgba(var(--SmartThemeCheckboxBgColorR),var(--SmartThemeCheckboxBgColorG),var(--SmartThemeCheckboxBgColorB),0.3);
    --crimson70a: var(--SmartThemeBodyColor);
    /* 适配 */
    --性别: "女";
    --user生日: "1961-01-01";
    --char生日: "1961-09-01";
    --有效时间: "\221E";
    --user思维链文字: "捡到大佬的学生证怎么办？！";
  }

  /* 🐧字体使用 */
  body {
    font-family: var(--font1);
    font-weight: normal;
  }

  /* 🐦顶栏 */
  /* 顶栏背景 */
  #top-settings-holder {
    background-color: var(--SmartThemeQuoteColor);
    box-shadow:
      0 0 10px var(--SmartThemeBotMesBlurTintColor),
      0 0 25px var(--SmartThemeBotMesBlurTintColor),
      0 8px 40px var(--SmartThemeBotMesBlurTintColor),
      0 4px 5px rgba(0, 0, 0, 0.2);
  }

  /* 去顶栏阴影 */
  #top-bar {
    box-shadow: none !important;
  }

  /* 顶栏图标大小 */
  #top-settings-holder .drawer-icon::before {
    font-size: 18px;
  }

  /* 🐤聊天区域 */
  #chat {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow: none !important;
    /* 居中 */
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    /* 气泡与底部距离 */
    padding-bottom: 120px !important;
  }

  /* 消息顶部留空 */
  .mes {
    top: 100px;
    position: relative !important;
  }

  /* 消息留空 */
  .mes + .mes {
    margin-top: 100px;
  }

  /* 气泡背景 */
  .mes {
    background-color: white !important;
    width: 95%;
    border-radius: 0px !important;
    align-self: center !important;
    display: flex !important;
    margin: 0 auto;
    box-shadow:
      0 0px 10px var(--SmartThemeBotMesBlurTintColor),
      0 0 25px var(--SmartThemeBotMesBlurTintColor);
    padding-top: 10px !important;
    padding-bottom: 10px !important;
    padding-left: 0px !important;
    padding-right: 0px !important;
    flex-direction: column !important;
    overflow: visible !important; /* 允许溢出 */
    z-index: -10;
  }

  /* 横线 */
  .mes::before {
    content: '';
    position: absolute;
    left: 2%;
    right: 2%;
    top: 0;
    bottom: 0;
    background-image: repeating-linear-gradient(
        to bottom,
        var(--SmartThemeUserMesBlurTintColor) 0px,
        var(--SmartThemeUserMesBlurTintColor) 1px,
        transparent 1px,
        transparent 1.8em
    );
    pointer-events: none;
    z-index: -9;
  }

  /* 底部色条 */
  .mes_block {
    position: relative;
    overflow: visible !important; /* 允许溢出 */
  }

  .mes_block::before {
    content: '';
    position: absolute;
    bottom: -11px;
    left: -0.1%;
    right: -0.1%;
    height: 2.7rem;
    background-color: var(--SmartThemeQuoteColor);
    pointer-events: none;
    z-index: -2;
  }

  /* 顶部色条 */
  .mes::after {
    content: '';
    position: absolute;
    top: -2px;
    left: -0.1%;
    right: -0.1%;
    height: 3.6rem;
    background-color: var(--SmartThemeQuoteColor);
    pointer-events: none;
    z-index: -2;
  }

  /* 顶部文字 */
  .mes_block::after {
    content: "NO.\A DATE.";
    white-space: pre-line;
    position: absolute;
    top: -7px;
    right: 78px;
    font-family: var(--font2);
    font-size: 9px;
    font-weight: normal;
    color: var(--SmartThemeBodyColor);
    line-height: 2.8;
    text-align: left;
    pointer-events: none;
    z-index: -1;
  }

  /* 🐣文字效果 */
  .mes_text {
    padding-top: 0px !important;
    padding-right: 3px !important;
    padding-left: 0px !important;
    padding-bottom: 50px !important;
  }

  /* 消息块顶部留白 */
  .mes_block {
    padding-top: 90px;
  }

  /* 引用文字 */
  q {
    background-color: var(--SmartThemeQuoteColor) !important;
    color: var(--SmartThemeBodyColor) !important;
    border-radius: 0px !important;
    padding: 1px 6px;
    line-height: 1.6;
    text-shadow: none;
  }

  /* 引用块 */
  .mes_text blockquote {
    background-color: white !important;
      border-left: 4px solid var(--SmartThemeBodyColor) !important;
      box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.2) !important;
      margin: 5px 0 !important;
      padding: 5px 10px !important;
      border-radius: 0px !important;
  }

  /* 代码块 */
  .mes_text code {
    color: var(--SmartThemeBodyColor);
    background-color: white !important;
    border-left: 4px solid var(--SmartThemeBodyColor) !important;
    box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.2) !important;
    font-family: var(--font1) !important;
    border-radius: 0px !important;
  }

  /* 🍹页码区 */
  /* 左箭头 */
  #chat .mes .swipe_left,
  .mes .swipe_left {
      position: absolute !important;
      left: 0px !important; 
      top: auto !important;
      bottom: 0px !important;
      margin: 0 !important; 
      height: 40px !important;
      width: 40px !important;
      float: none !important;
      opacity: 1 !important;
  }

  /* 右箭头容器 */
  #chat .mes .swipeRightBlock,
  .mes .swipeRightBlock {
      position: absolute !important;
      right: 0px !important; 
      top: auto !important; 
      bottom: -21px !important; 
      transform: none !important; 
      width: auto !important; 
      margin: 0 !important;
      display: block !important;
      float: none !important;
  }

  /* 右箭头图标 */
  #chat .mes .swipeRightBlock .swipe_right,
  .mes .swipeRightBlock .swipe_right {
      height: 40px !important;
      width: 40px !important; 
      opacity: 1 !important;
  }

  /* 页码 */
  .swipes-counter {
    font-family: var(--font2) !important;
    font-size: 13px !important;
    opacity: 1 !important;
    text-align: center !important;
    position: relative !important;
    top: -29px !important;
    left: -30px !important;
color: var(--SmartThemeBodyColor);
  }

  .mes:not(:last-of-type) .swipes-counter {
    display: none !important;
  }

  .mes:has(.swipe_left[style*="none"]):has(.swipe_right[style*="none"]) .swipes-counter {
    display: none !important;
  }

  /* 🕊️名字和时间戳 */
  .mes .ch_name.flex-container {
    z-index: 20 !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    width: 100% !important;
    margin: 0 !important;
    justify-content: flex-start !important;
    align-items: flex-start !important;
  }

  /* 名字 */
  .mes .ch_name.flex-container .name_text {
    font-family: var(--font2) !important;
    text-shadow: none !important;
    font-weight: normal !important;
    font-style: normal !important;
    text-decoration: none !important;
    letter-spacing: normal !important;
    font-size: 8px !important;
    position: relative !important;
    top: -66px !important;
    left: 138px !important;
    margin: 0 !important;
    padding: 0 8px !important;
    display: inline-block !important;
    width: 58px !important;
    box-sizing: border-box !important;
    height: auto !important;
    opacity: 1 !important;
    white-space: nowrap !important;
    text-align: center !important;
    transform: rotate(-6deg) !important;
  }

  /* 生日 */
  .mes[is_user="true"] .ch_name.flex-container::before {
    content: var(--user生日) !important;
    position: absolute !important;
    top: 8.5px !important;
    left:134.5px !important;
    width: 100px !important;
    box-sizing: border-box !important;
    font-family: var(--font2) !important;
    font-size: 8px !important;
    font-weight: normal !important;
    text-align: center !important;
    transform: rotate(-6deg) !important;
    pointer-events: none !important;
  }

  .mes:not([is_user="true"]) .ch_name.flex-container::before {
    content: var(--char生日) !important;
    position: absolute !important;
    top: 8.5px !important;
    left: 134.5px !important;
    width: 100px !important;
    box-sizing: border-box !important;
    font-family: var(--font2) !important;
    font-size: 8px !important;
    font-weight: normal !important;
    text-align: center !important;
    transform: rotate(-6deg) !important;
    pointer-events: none !important;
  }

  /* 性别 */
  .mes[is_user="true"] .ch_name.flex-container::after {
    content: var(--性别) !important;
    position: absolute !important;
    top: -15.5px !important;
    left: 145px !important;
    width: 57px !important;
    box-sizing: border-box !important;
    font-family: var(--font2) !important;
    font-size: 8px !important;
    font-weight: normal !important;
    text-align: center !important;
    transform: rotate(-6deg) !important;
    pointer-events: none !important;
  }

  .mes:not([is_user="true"]) .ch_name.flex-container::after {
    content: "男" !important;
    position: absolute !important;
    top: -16px !important;
    left: 145px !important;
    width: 57px !important;
    box-sizing: border-box !important;
    font-family: var(--font2) !important;
    font-size: 8px !important;
    font-weight: normal !important;
    text-align: center !important;
    transform: rotate(-6deg) !important;
    pointer-events: none !important;
  }

  /* 时间戳 */
  .mes .ch_name.flex-container .timestamp {
    font-family: var(--font2) !important;
    /* 去除所有其他文字效果 */
    text-shadow: none !important;
    font-weight: normal !important;
    font-style: normal !important;
    text-decoration: none !important;
    letter-spacing: normal !important;
    font-size: 7px !important;
    position: absolute !important;
    top: 26.5px !important;
    right: 6px !important;
    /* 固定区域 */
    display: inline-block !important;
    opacity: 1 !important;
    text-align: right !important;
  }

  /* 🌵头像区域 */
  .mesAvatarWrapper {
    position: absolute !important;
    top: 40px !important;
    left: -20px !important;
    right: 0 !important;
    width: 100% !important;
    margin: 0 !important;
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: flex-start !important; /* 内容居左 */
    flex-wrap: nowrap !important; /* 不换行 */
    height: auto !important;
  }

  /* 头像 */
  .mesAvatarWrapper .avatar {
    position: absolute !important;
    top: -60px !important;
    left: 80px !important;
    transform: translateX(-50%) rotate(-6deg) !important;
    /* 长方形 */
    border-radius: 0 !important;
    border: 0px !important;
    width: 42px !important;
    height: 63px !important;
    aspect-ratio: 2/3 !important;
    overflow: visible !important; /* 允许头像框溢出 */
    /* 布局 */
    display: flex !important;
    justify-content: center;
    align-items: center;
  }

  /* 学生证 */
  .mesAvatarWrapper .avatar::before {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    top: -91px !important;
    left: 74.5px !important;
    transform: translateX(-50%) !important;
    width: 220px !important;
    height: 230px !important;
    margin-top: 8px !important;
    background: url(https://iili.io/qJNrePj.png) no-repeat center/contain !important;
    z-index: -1 !important;
    pointer-events: none !important;
  }

  /* 底色 */
  .mesAvatarWrapper .avatar::after {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    top: -36px !important;
    left: 75px !important;
    transform: translateX(-50%) !important;
    width: 205px !important;
    height: 135px !important;
    background: var(--SmartThemeBodyColor) !important;
    z-index: -2 !important;
    pointer-events: none !important;
  }

  /* 楼层 */
  .mesAvatarWrapper .mesIDDisplay {
    position: absolute !important;
    font-family: var(--font2) !important;
    top: -29px !important;
    right: 32px !important;
    width: 42px !important;
    box-sizing: border-box !important;
    padding: 0 6px !important;
    text-shadow: none !important;
    background: transparent !important;
    margin: 0 !important;
    line-height: 1 !important;
    font-weight: normal !important;
    opacity: 1 !important;
    text-align: left !important;
    white-space: nowrap !important;
    font-size: 9px !important;
  }

  /* 时间 */
  .mesAvatarWrapper .mes_timer {
    position: absolute !important;
    font-family: var(--font2) !important;
    top: 4px !important;
    left: 187px !important;
    width: 38px !important;
    box-sizing: border-box !important;
    text-shadow: none !important;
    margin: 0 !important;
    padding: 0 8px !important;
    line-height: 1 !important;
    font-weight: normal !important;
    opacity: 1 !important;
    text-align: center !important;
    white-space: nowrap !important;
    font-size: 8px !important;
    transform: rotate(-6deg) !important;
  }

  /* 有效时间 */
  .mes[is_user="true"] .mesAvatarWrapper .tokenCounterDisplay::after {
    content: var(--有效时间) !important;
    position: absolute !important;
    top: 75px !important;
    left: 16px !important;
    width: 42px !important;
    font-family: var(--font2) !important;
    font-size: 8px !important;
    font-weight: normal !important;
    pointer-events: none !important;
  }

  /* token  */
  .mesAvatarWrapper .tokenCounterDisplay {
    position: absolute !important;
    font-family: var(--font2) !important;
    top: -69.5px !important;
    left: 162px !important;
    width: 58px !important;
    box-sizing: border-box !important;
    text-shadow: none !important;
    margin: 0 !important;
    padding: 0 8px !important;
    line-height: 1 !important;
    font-weight: normal !important;
    opacity: 1 !important;
    text-align: center !important;
    white-space: nowrap !important;
    font-size: 8px !important;
    transform: rotate(-6deg) !important;
  }

  /* 头像图片 */
  .mesAvatarWrapper .avatar img {
    border: 0px !important;
    border-radius: 0 !important;
    width: 100% !important;
    height: 100% !important;
    /* 裁剪位置 */
    object-fit: cover !important;
    object-position: 50% 50% !important;
    transform: scale(1.0);
  }

  /* 🌿思维链 */
  .mes_reasoning_header.flex-container {
    /* 位置 */
    position: absolute !important;
    top: 63px !important;
    right: 15px !important;
    transform: none !important;
    /* 宽度 */
    width: 142px !important;
    background-color: white !important;
    border-left: 4px solid var(--SmartThemeBodyColor) !important;
    box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.2) !important;
    border-radius: 0 !important;
    padding: 3px 10px !important;
    /* 居中对齐 */
    justify-content: center !important;
    align-items: center !important;
  }

  /* 隐藏原有箭头图标 */
  .mes_reasoning_header.flex-container .mes_reasoning_arrow {
    display: none !important;
  }

  /* 思维链文字 */
  .mes_reasoning_header_title {
      color: var(--color3) !important;
      /* 隐藏原有文字 */
      visibility: hidden !important;
      position: relative !important;
      width: 100% !important;
      text-align: center !important;
      /* 控制新文字大小 */
      font-size: 9px !important; 
  }

  /* 使用伪元素替换文字 */
  .mes_reasoning_header_title::after {
      content: "好學生背地裡會是大佬嗎？";
      visibility: visible !important;
      position: absolute !important;
      left: 0 !important;
      right: 0 !important;
      top: 0 !important;
      text-align: center !important;
  }

  /* 思维链配平  */
  .mes[is_user="true"] .ch_name.flex-container .timestamp::after {
    content: var(--user思维链文字) !important;
    position: absolute !important;
    top: 38px !important;
    left: -90px !important;
    margin-top: 6px !important;
    width: 142px !important;
    box-sizing: border-box !important;
    padding: 3px 10px !important;
    text-align: center !important;
    display: block !important;
    color: var(--SmartThemeBodyColor) !important;
    background-color: white !important;
    border-left: 4px solid var(--SmartThemeBodyColor) !important;
    box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.2) !important;
    font-family: var(--font1) !important;
    font-size: 10px !important;
    border-radius: 0 !important;
    white-space: normal !important;
    pointer-events: none !important;
  }

  .mes_reasoning {
    color: var(--SmartThemeBodyColor) !important;
    padding: 5px 10px !important;
    margin-top: 0px !important;
    margin-bottom: 10px !important;
    background-color: white !important;
      border-left: 4px solid var(--SmartThemeBodyColor) !important;
      box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.2) !important;
      padding: 5px 10px !important;
      border-radius: 0px !important;
      margin-bottom: 15px !important;
  }

  /* ☘️按钮 */
  .mes_buttons {
    position: absolute !important;
    top: -5px !important;
    right: 5px !important;
    display: flex !important;
    justify-content: flex-end !important;
    /* 去除阴影 */
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;
    backdrop-filter: none !important;
    overflow: visible !important;
font-size: 13px;
  }

  /* 去除效果 */
  .mes_buttons .mes_button {
    opacity: 1 !important; /* 不透明 */
    box-shadow: none !important; /* 无阴影 */
    text-shadow: none !important;
    transition: none !important; /* 去除动画过渡 */
    filter: none !important;
    backdrop-filter: none !important;
    border-radius: 0 !important; /* 防止圆形裁剪 */
    overflow: visible !important; /* 允许图标完整显示 */
  }

  /* 按钮组按钮 */
  .extraMesButtons .mes_button {
    display: flex !important;
  }

  /* 按钮图标替换 */
  .mes_buttons > .mes_button {
    width: 20px !important;
    height: 20px !important;
    border: none !important;
    border-radius: 0 !important;
    overflow: visible !important;
  }

  /* 编辑时的按钮左移 */
  .mes_edit_buttons {
    margin-right: 60px !important;
  }

  /* 取消按钮字色 */
  .mes_edit_cancel,
  .mes_reasoning_edit_cancel {
    color: var(--SmartThemeQuoteColor) !important;
  }

  /* 思维链编辑 */
  .mes_reasoning_details:not([open]) .mes_reasoning_actions {
    display: none !important;
  }

  /* 思维链按钮下移 */
  .mes_reasoning_actions {
    position: absolute !important;
    top: 48px !important;
    right: 0px !important;
    margin: 0 !important;
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;
    backdrop-filter: none !important;
  }

  /* 思维链按钮 */
  .mes_reasoning_actions .mes_button,
  .mes_reasoning_actions .menu_button {
    box-shadow: none !important;
    text-shadow: none !important;
    opacity: 1 !important;
    filter: none !important;
    transition: none !important;
  }

  /* 思维链替换*/
  .mes_reasoning_actions .mes_button {
    width: 20px !important;
    height: 20px !important;
  }

  /* 🎋底栏 */
  #nonQRFormItems {
    background-color: var(--SmartThemeQuoteColor) !important;
    border-radius: 0px !important;
    padding: 0px 0px !important;
    position: relative !important;
    overflow: visible !important; /* 防止裁剪 */
box-shadow:
      0 0 10px var(--SmartThemeBotMesBlurTintColor),
      0 0 25px var(--SmartThemeBotMesBlurTintColor),
      0 8px 40px var(--SmartThemeBotMesBlurTintColor),
      0 -2px 5px rgba(0, 0, 0, 0.2);
  }

  /* 发送表单 */
  #send_form {
    border-radius: 0 !important;
  }

  /* 左右按钮容器垂直居中 */
  #leftSendForm,
  #rightSendForm {
    display: flex !important;
    align-items: center !important; /* 垂直居中 */
  }

  /* 底栏图标大小 */
  #leftSendForm > div,
  #rightSendForm > div,
  #rightSendForm i {
    font-size: 18px !important;
color: var(--SmartThemeBodyColor);
  }

  /* 输入框 */
  #send_textarea {
    clip-path: none !important; /* 防止被裁剪 */
    background-color: transparent !important;
    color: var(--SmartThemeBodyColor) !important;
    border: none !important;
    margin: 0px 0px !important;
    resize: none !important;
  }

  /* 输入框底色 */
  input:not([type="checkbox"]):not([type="range"]):not([type="file"]),
  textarea:not(#send_textarea):not([data-for="customCSS"]):not(.popup-input),
  select {
    background-color: rgba(var(--SmartThemeCheckboxBgColorR),var(--SmartThemeCheckboxBgColorG),var(--SmartThemeCheckboxBgColorB),0.3) !important;
    border: 1.5px solid var(--color3) !important;
    color: var(--SmartThemeBodyColor) !important;
    padding-bottom: 5px;
    padding-top: 5px;
    font-family: var(--font1) !important;
    resize: none !important;
    /* 隐藏下拉箭头 */
    appearance: none !important;
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    -ms-appearance: none !important;
    background-image: none !important;
  }

  /* 底栏输入框 */
